CREATE OR REPLACE FUNCTION public.atlas_wb_ensure_world_root_map(p_world uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_id UUID;
BEGIN
  SELECT id INTO v_id
  FROM public.world_atlas_maps
  WHERE world_profile_id = p_world
    AND kind = 'world'
    AND parent_map_id IS NULL
  ORDER BY sort_order ASC, created_at ASC
  LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO public.world_atlas_maps (
      world_profile_id, parent_map_id, kind, title, sort_order, bounds, generator_meta
    ) VALUES (
      p_world, NULL, 'world', 'Weltkarte', 0,
      '{"minX":0,"minY":0,"maxX":1000,"maxY":1000}'::jsonb,
      jsonb_build_object('engine', 'unified_canvas', 'mapStatus', 'unsketched')
    )
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$

CREATE OR REPLACE FUNCTION public.atlas_wb_is_canonical_kind(p_kind text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT p_kind IN ('continent', 'country', 'place', 'building', 'room');
$$

CREATE OR REPLACE FUNCTION public.atlas_wb_next_placeholder_name(p_world uuid, p_parent uuid, p_kind text) RETURNS text LANGUAGE plpgsql SET search_path TO 'public' AS $$
DECLARE
  v_stem TEXT := public.atlas_wb_placeholder_stem(p_kind);
  v_n INT;
BEGIN
  SELECT COUNT(*)::INT + 1 INTO v_n
  FROM public.world_places
  WHERE world_profile_id = p_world
    AND kind = p_kind
    AND status = 'placeholder'
    AND (
      (p_parent IS NULL AND parent_place_id IS NULL)
      OR parent_place_id = p_parent
    );
  RETURN v_stem || ' ' || v_n::TEXT;
END;
$$

CREATE OR REPLACE FUNCTION public.atlas_wb_place_row(p_world uuid, p_place uuid) RETURNS public.world_places LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_row public.world_places%ROWTYPE;
BEGIN
  SELECT * INTO v_row
  FROM public.world_places
  WHERE id = p_place AND world_profile_id = p_world;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
  END IF;
  RETURN v_row;
END;
$$

