CREATE OR REPLACE FUNCTION public.build_dornhain_starter_map_data(p_size integer = 24) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  n INT := GREATEST(16, LEAST(COALESCE(p_size, 24), 40));
  v_tiles JSONB := '{}'::jsonb;
  v_x INT;
  v_y INT;
  v_type TEXT;
  v_key TEXT;
BEGIN
  FOR v_y IN 0 .. (n - 1) LOOP
    FOR v_x IN 0 .. (n - 1) LOOP
      v_type := 'grass';
      IF v_x <= 2 OR (v_x <= 4 AND v_y >= n - 6) THEN
        v_type := 'water';
      ELSIF v_y <= 2 OR (v_y <= 4 AND v_x >= n - 8) THEN
        v_type := 'mountain';
      ELSIF v_x >= n - 5 OR (v_x >= n - 7 AND v_y >= 10 AND v_y <= 18) THEN
        v_type := 'forest';
      END IF;
      -- roads market↔tavern↔woods
      IF (v_y = 11 AND v_x BETWEEN 8 AND 12)
         OR (v_x = 10 AND v_y BETWEEN 10 AND 12)
         OR (v_y = 12 AND v_x BETWEEN 12 AND 16) THEN
        v_type := 'road';
      END IF;
      IF (v_x = 8 AND v_y = 12)
         OR (v_x = 12 AND v_y = 10)
         OR (v_x = 16 AND v_y = 14)
         OR (v_x = 18 AND v_y = 8) THEN
        v_type := 'city';
      END IF;
      v_key := v_x::text || ',' || v_y::text;
      v_tiles := jsonb_set(
        v_tiles,
        ARRAY[v_key],
        jsonb_build_object('type', v_type, 'countryId', NULL),
        true
      );
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'size', n,
    'tiles', v_tiles,
    'countries', '[]'::jsonb,
    'pins', jsonb_build_array(
      jsonb_build_object('id', 'pin.tavern', 'title', 'Taverne', 'x', 8, 'y', 12, 'discovered', true, 'locationRef', 'loc.tavern'),
      jsonb_build_object('id', 'pin.market', 'title', 'Markt', 'x', 12, 'y', 10, 'discovered', true, 'locationRef', 'loc.market'),
      jsonb_build_object('id', 'pin.woods', 'title', 'Wald', 'x', 16, 'y', 14, 'discovered', true, 'locationRef', 'loc.woods'),
      jsonb_build_object('id', 'pin.crypt', 'title', 'Krypta', 'x', 18, 'y', 8, 'discovered', false, 'locationRef', 'loc.crypt')
    )
  );
END;
$$

CREATE OR REPLACE FUNCTION public.build_dornhain_unified_generator_meta() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path TO 'public', 'pg_temp' AS $$
  SELECT $dornhain_meta${"engine":"unified_canvas","sagaSlug":"dornhain.whisper","seed":"dornhain.unified.v3","scale":"world","unifiedCanvas":{"format":"sagatree-unified-atlas-v1","layers":{"terrain":true,"roads":true,"region":true,"city":true,"interior":true,"drawings":true,"objects":true,"grid":false},"strokes":[],"objects":[],"rooms":[{"id":"w.ocean","material":"wasser","x":0,"y":0,"w":1000,"h":1000}],"walls":[],"demoSeed":false}}$dornhain_meta$::jsonb;
$$

CREATE OR REPLACE FUNCTION public.can_view_saga_binding(p_project_id uuid, p_reveal text, p_asset_kind text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_hidden_key TEXT;
  v_read_key TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RETURN false;
  END IF;
  IF NOT public.current_user_is_active_project_member(p_project_id)
     AND NOT public.is_project_gm(p_project_id, v_uid) THEN
    RETURN false;
  END IF;

  IF p_reveal = 'unlisted' THEN
    -- Not in list RPCs; deep-link / GM with secrets only.
    RETURN public.has_saga_permission(p_project_id, 'saga.secrets.read')
        OR public.has_saga_permission(p_project_id, 'saga.secrets.reveal')
        OR public.is_project_gm(p_project_id, v_uid);
  END IF;

  IF p_reveal = 'gm_only' THEN
    v_hidden_key := CASE p_asset_kind
      WHEN 'npc' THEN 'saga.npc.read_hidden'
      WHEN 'item' THEN 'saga.items.read_hidden'
      WHEN 'quest' THEN 'saga.quests.read_hidden'
      WHEN 'lore' THEN 'saga.lore.read_hidden'
      ELSE 'saga.secrets.read'
    END;
    RETURN public.has_saga_permission(p_project_id, v_hidden_key)
        OR public.has_saga_permission(p_project_id, 'saga.secrets.read')
        OR public.is_project_gm(p_project_id, v_uid);
  END IF;

  -- party
  v_read_key := CASE p_asset_kind
    WHEN 'character' THEN 'saga.characters.read'
    WHEN 'npc' THEN 'saga.npc.read'
    WHEN 'item' THEN 'saga.items.read'
    WHEN 'quest' THEN 'saga.quests.read'
    WHEN 'map' THEN 'saga.world.read'
    WHEN 'location' THEN 'saga.world.read'
    WHEN 'lore' THEN 'saga.lore.read'
    ELSE 'saga.workspace.access'
  END;
  RETURN public.has_saga_permission(p_project_id, v_read_key)
      OR public.is_project_gm(p_project_id, v_uid);
END;
$$

