CREATE OR REPLACE FUNCTION public.forbid_public_id_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.public_id IS DISTINCT FROM OLD.public_id THEN
    RAISE EXCEPTION 'public_id is immutable';
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION generate_project_code() RETURNS trigger AS $$
BEGIN
  IF NEW.code IS NULL OR NEW.code = '' THEN
    NEW.code := UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 8));
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.generate_sagatree_public_id(p_prefix text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  alphabet TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  body TEXT;
  i INT;
  idx INT;
  has_letter BOOLEAN;
  has_digit BOOLEAN;
  ch TEXT;
  attempt INT := 0;
BEGIN
  IF p_prefix IS NULL OR length(p_prefix) < 2 THEN
    RAISE EXCEPTION 'invalid public id prefix';
  END IF;

  LOOP
    attempt := attempt + 1;
    IF attempt > 64 THEN
      RAISE EXCEPTION 'failed to generate public id body';
    END IF;

    body := '';
    FOR i IN 1..5 LOOP
      idx := 1 + (get_byte(gen_random_bytes(1), 0) % length(alphabet));
      body := body || substr(alphabet, idx, 1);
    END LOOP;

    has_letter := body ~ '[A-Z]';
    has_digit := body ~ '[2-9]';
    IF has_letter AND has_digit THEN
      RETURN upper(p_prefix) || '-' || body;
    END IF;
  END LOOP;
END;
$$

CREATE OR REPLACE FUNCTION public.generate_session_invite_token() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  candidate TEXT;
  attempt INT := 0;
BEGIN
  LOOP
    attempt := attempt + 1;
    IF attempt > 16 THEN
      RAISE EXCEPTION 'session invite token collision retries exhausted' USING ERRCODE = 'P0001';
    END IF;
    candidate := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.session_invites i WHERE i.token = candidate
    );
  END LOOP;
  RETURN candidate;
END;
$$

