CREATE OR REPLACE FUNCTION public.join_project_by_code(p_code text, p_character_id uuid = NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_project_id UUID;
  v_existing_status TEXT;
  v_sheet_status TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(BTRIM(p_code), '') IS NULL THEN
    RAISE EXCEPTION 'Project code is required' USING ERRCODE = '22023';
  END IF;

  SELECT id
  INTO v_project_id
  FROM public.projects
  WHERE UPPER(BTRIM(code)) = UPPER(BTRIM(p_code))
    AND status = 'active';

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'Project not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT status
  INTO v_existing_status
  FROM public.project_members
  WHERE project_id = v_project_id
    AND user_id = v_user_id;

  IF FOUND THEN
    RAISE EXCEPTION 'Project membership already exists with status %', v_existing_status
      USING ERRCODE = 'P0001';
  END IF;

  IF p_character_id IS NOT NULL THEN
    SELECT sheet_status
    INTO v_sheet_status
    FROM public.characters
    WHERE id = p_character_id
      AND owner_user_id = v_user_id
      AND character_type = 'pc';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Character is not owned by the current user' USING ERRCODE = '42501';
    END IF;

    IF COALESCE(v_sheet_status, 'complete') <> 'complete' THEN
      RAISE EXCEPTION 'Unvollständige Charakterbögen können keinem Abenteuer beitreten'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.project_members (
    project_id,
    user_id,
    character_id,
    role,
    status
  ) VALUES (
    v_project_id,
    v_user_id,
    p_character_id,
    'player',
    'active'
  );

  RETURN v_project_id;
END;
$$

CREATE OR REPLACE FUNCTION public.join_session_by_code(p_code text, p_character_id uuid = NULL) RETURNS public.sessions LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_sheet_status TEXT;
  v_revision BIGINT;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  IF NULLIF(BTRIM(p_code), '') IS NULL THEN RAISE EXCEPTION 'Session code is required' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_session FROM public.sessions
   WHERE code IS NOT NULL AND UPPER(BTRIM(code)) = UPPER(BTRIM(p_code)) LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002'; END IF;
  IF v_session.status = 'completed' THEN RAISE EXCEPTION 'Session is completed' USING ERRCODE = '22023'; END IF;
  IF p_character_id IS NOT NULL THEN
    SELECT sheet_status INTO v_sheet_status FROM public.characters
     WHERE id = p_character_id AND owner_user_id = actor AND character_type = 'pc';
    IF NOT FOUND THEN RAISE EXCEPTION 'Character is not owned by the current user' USING ERRCODE = '42501'; END IF;
    IF COALESCE(v_sheet_status, 'complete') <> 'complete' THEN
      RAISE EXCEPTION 'Unvollständige Charakterbögen können keiner Session beitreten' USING ERRCODE = '22023';
    END IF;
  END IF;
  PERFORM public.ensure_active_project_player(v_session.project_id, actor, p_character_id);
  INSERT INTO public.session_players (session_id, user_id, character_id, is_online)
  VALUES (v_session.id, actor, p_character_id, true)
  ON CONFLICT (session_id, user_id) DO UPDATE
    SET character_id = COALESCE(EXCLUDED.character_id, public.session_players.character_id),
        is_online = true, left_at = NULL;

  v_revision := COALESCE(v_session.runtime_revision, 0) + 1;
  UPDATE public.sessions
     SET runtime_revision = v_revision, updated_at = NOW()
   WHERE id = v_session.id
  RETURNING * INTO v_session;

  PERFORM public.append_session_event(
    v_session.id,
    'join',
    actor,
    jsonb_build_object('characterId', p_character_id),
    v_revision,
    NULL
  );

  RETURN v_session;
END;
$$

CREATE OR REPLACE FUNCTION public.leave_play_session(p_session_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_revision BIGINT;
  v_removed INT := 0;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    DELETE FROM public.session_players WHERE session_id = p_session_id AND user_id = actor;
    RETURN;
  END IF;

  DELETE FROM public.session_players
   WHERE session_id = p_session_id AND user_id = actor;
  GET DIAGNOSTICS v_removed = ROW_COUNT;

  IF v_removed = 0 THEN
    -- Foreign / non-participant leave is a no-op (no revision bump, no event).
    RETURN;
  END IF;

  v_revision := COALESCE(v_session.runtime_revision, 0) + 1;
  UPDATE public.sessions
     SET runtime_revision = v_revision, updated_at = NOW()
   WHERE id = p_session_id;
  PERFORM public.append_session_event(
    p_session_id,
    'leave',
    actor,
    '{}'::jsonb,
    v_revision,
    NULL
  );
END;
$$

CREATE OR REPLACE FUNCTION public.list_saga_bindings(p_public_id text, p_asset_kind text = NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_project_id UUID;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT id INTO v_project_id
  FROM public.projects
  WHERE public_id = UPPER(BTRIM(p_public_id));

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'saga not found';
  END IF;

  IF NOT public.current_user_is_active_project_member(v_project_id)
     AND NOT public.is_project_gm(v_project_id, v_uid) THEN
    RAISE EXCEPTION 'not a member';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', b.id,
        'assetKind', b.asset_kind,
        'assetId', b.asset_id,
        'reveal', b.reveal,
        'label', b.label,
        'metadata', b.metadata,
        'worldPlaceId', b.world_place_id
      )
      ORDER BY b.asset_kind, b.label, b.asset_id
    )
    FROM public.saga_asset_bindings b
    WHERE b.project_id = v_project_id
      AND (p_asset_kind IS NULL OR b.asset_kind = p_asset_kind)
      AND public.can_view_saga_binding(b.project_id, b.reveal, b.asset_kind)
      AND b.reveal <> 'unlisted'
  ), '[]'::jsonb);
END;
$$

CREATE OR REPLACE FUNCTION public.list_saga_member_permission_state(p_public_id text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_project_id UUID;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT id INTO v_project_id
  FROM public.projects
  WHERE public_id = UPPER(BTRIM(p_public_id));

  IF v_project_id IS NULL THEN
    RAISE EXCEPTION 'saga not found';
  END IF;

  IF NOT public.has_saga_permission(v_project_id, 'saga.members.read')
     AND NOT public.is_project_gm(v_project_id, v_uid) THEN
    RAISE EXCEPTION 'missing saga.members.read';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'memberId', m.id,
        'userId', m.user_id,
        'role', m.role,
        'status', m.status,
        'bundleId', b.bundle_id,
        'canSetBundle', public.has_saga_permission(v_project_id, 'saga.members.set_bundle')
          OR public.is_project_gm(v_project_id, v_uid)
      )
      ORDER BY m.joined_at
    )
    FROM public.project_members m
    LEFT JOIN public.project_member_saga_bundles b ON b.member_id = m.id
    WHERE m.project_id = v_project_id AND m.status = 'active'
  ), '[]'::jsonb);
END;
$$

CREATE OR REPLACE FUNCTION public.list_world_atlas_maps(p_world_profile_id uuid, p_player_view boolean = FALSE, p_saga_public_id text = NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_user UUID := auth.uid();
  v_rows JSONB;
  v_can_edit BOOLEAN;
  v_party_only BOOLEAN;
  v_project UUID;
  v_allowed UUID[];
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_world_profile_id IS NULL THEN
    RAISE EXCEPTION 'world_profile_id required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_read_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_can_edit := public.current_user_can_edit_world_profile(p_world_profile_id);
  v_party_only := (NOT v_can_edit) OR (p_player_view IS TRUE);

  IF p_saga_public_id IS NOT NULL AND btrim(p_saga_public_id) <> '' THEN
    v_project := public.atlas_wb_resolve_saga_project(p_world_profile_id, p_saga_public_id);
    IF v_project IS NULL THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF NOT public.current_user_is_active_project_member(v_project) THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_party_only THEN
    IF v_project IS NULL THEN
      RETURN jsonb_build_object('maps', '[]'::jsonb);
    END IF;
    v_allowed := public.atlas_wb_party_revealed_map_ids(p_world_profile_id, v_project);

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', m.id,
        'worldProfileId', m.world_profile_id,
        'parentMapId', CASE
          WHEN m.parent_map_id IS NULL THEN NULL
          WHEN m.parent_map_id = ANY (v_allowed) THEN m.parent_map_id
          ELSE NULL
        END,
        'kind', m.kind,
        'title', m.title,
        'sortOrder', m.sort_order,
        'revision', m.revision,
        'updatedAt', m.updated_at,
        'hasAzgaarMap', false,
        'hasBasemap', m.basemap_storage_path IS NOT NULL
      )
      ORDER BY m.sort_order, m.title
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_atlas_maps m
    WHERE m.world_profile_id = p_world_profile_id
      AND m.id = ANY (v_allowed);
  ELSE
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', m.id,
        'worldProfileId', m.world_profile_id,
        'parentMapId', m.parent_map_id,
        'kind', m.kind,
        'title', m.title,
        'sortOrder', m.sort_order,
        'revision', m.revision,
        'updatedAt', m.updated_at,
        'hasAzgaarMap', m.azgaar_map_storage_path IS NOT NULL,
        'hasBasemap', m.basemap_storage_path IS NOT NULL
      )
      ORDER BY m.sort_order, m.title
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_atlas_maps m
    WHERE m.world_profile_id = p_world_profile_id;
  END IF;

  RETURN jsonb_build_object('maps', COALESCE(v_rows, '[]'::jsonb));
END;
$$

CREATE OR REPLACE FUNCTION public.list_world_place_map_links(p_world_profile_id uuid, p_player_view boolean = FALSE, p_saga_public_id text = NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_user UUID := auth.uid();
  v_project UUID;
  v_rows JSONB;
  v_can_edit BOOLEAN;
  v_party_only BOOLEAN;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_read_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_can_edit := public.current_user_can_edit_world_profile(p_world_profile_id);
  v_party_only := (NOT v_can_edit) OR (p_player_view IS TRUE);

  IF p_saga_public_id IS NOT NULL AND btrim(p_saga_public_id) <> '' THEN
    SELECT id INTO v_project
    FROM public.projects
    WHERE public_id = upper(btrim(p_saga_public_id))
      AND world_profile_id = p_world_profile_id;
  END IF;

  IF v_party_only THEN
    IF v_project IS NULL THEN
      RETURN jsonb_build_object('links', '[]'::jsonb);
    END IF;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', l.id,
        'worldProfileId', l.world_profile_id,
        'placeId', l.place_id,
        'mapId', l.map_id,
        'usage', l.usage,
        'featureId', l.feature_id,
        'anchor', l.anchor
      )
      ORDER BY l.usage, l.created_at
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_place_map_links l
    INNER JOIN public.saga_asset_bindings b
      ON b.world_place_id = l.place_id
     AND b.project_id = v_project
     AND b.asset_kind = 'location'
     AND b.reveal = 'party'
    WHERE l.world_profile_id = p_world_profile_id;
  ELSE
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', l.id,
        'worldProfileId', l.world_profile_id,
        'placeId', l.place_id,
        'mapId', l.map_id,
        'usage', l.usage,
        'featureId', l.feature_id,
        'anchor', l.anchor
      )
      ORDER BY l.usage, l.created_at
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_place_map_links l
    WHERE l.world_profile_id = p_world_profile_id;
  END IF;

  RETURN jsonb_build_object('links', COALESCE(v_rows, '[]'::jsonb));
END;
$$

CREATE OR REPLACE FUNCTION public.list_world_places(p_world_profile_id uuid, p_player_view boolean = FALSE, p_saga_public_id text = NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_user UUID := auth.uid();
  v_project UUID;
  v_rows JSONB;
  v_can_edit BOOLEAN;
  v_party_only BOOLEAN;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_world_profile_id IS NULL THEN
    RAISE EXCEPTION 'world_profile_id required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_read_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_can_edit := public.current_user_can_edit_world_profile(p_world_profile_id);
  -- Non-editors always get party-filtered projection; editors only when player_view.
  v_party_only := (NOT v_can_edit) OR (p_player_view IS TRUE);

  IF p_saga_public_id IS NOT NULL AND btrim(p_saga_public_id) <> '' THEN
    SELECT id INTO v_project
    FROM public.projects
    WHERE public_id = upper(btrim(p_saga_public_id))
      AND world_profile_id = p_world_profile_id;
  END IF;

  IF v_party_only THEN
    IF v_project IS NULL THEN
      -- Fail closed: never dump full catalog for player / non-editor without saga.
      RETURN jsonb_build_object('places', '[]'::jsonb);
    END IF;

    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', p.id,
        'worldProfileId', p.world_profile_id,
        'parentPlaceId', p.parent_place_id,
        'kind', p.kind,
        'name', p.name,
        'description', p.description,
        'status', p.status,
        'seedKey', p.seed_key,
        'sortOrder', p.sort_order,
        'revision', p.revision,
        'bindingReveal', b.reveal,
        'bindingAssetId', b.asset_id
      )
      ORDER BY p.sort_order, p.name
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_places p
    INNER JOIN public.saga_asset_bindings b
      ON b.world_place_id = p.id
     AND b.project_id = v_project
     AND b.asset_kind = 'location'
     AND b.reveal = 'party'
    WHERE p.world_profile_id = p_world_profile_id
      AND p.status <> 'archived';
  ELSE
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', p.id,
        'worldProfileId', p.world_profile_id,
        'parentPlaceId', p.parent_place_id,
        'kind', p.kind,
        'name', p.name,
        'description', p.description,
        'status', p.status,
        'seedKey', p.seed_key,
        'sortOrder', p.sort_order,
        'revision', p.revision
      )
      ORDER BY p.sort_order, p.name
    ), '[]'::jsonb)
    INTO v_rows
    FROM public.world_places p
    WHERE p.world_profile_id = p_world_profile_id
      AND p.status <> 'archived';
  END IF;

  RETURN jsonb_build_object('places', COALESCE(v_rows, '[]'::jsonb));
END;
$$

CREATE OR REPLACE FUNCTION public.preview_world_node_consequences(p_world_profile_id uuid, p_place_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_desc UUID[];
  v_child INT;
  v_bind INT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  PERFORM public.atlas_wb_place_row(p_world_profile_id, p_place_id);

  v_desc := public.atlas_wb_descendant_ids(p_world_profile_id, p_place_id);
  v_child := COALESCE(cardinality(v_desc), 0);

  SELECT COUNT(*)::INT INTO v_bind
  FROM public.saga_asset_bindings b
  WHERE b.world_place_id = p_place_id
     OR b.world_place_id = ANY (v_desc);

  RETURN jsonb_build_object(
    'placeId', p_place_id,
    'childCount', v_child,
    'sagaBindingCount', v_bind,
    'requiresConfirm', (v_child > 0 OR v_bind > 0),
    'descendantIds', to_jsonb(v_desc)
  );
END;
$$

CREATE OR REPLACE FUNCTION public.promote_session_outcome_to_saga(p_session_id uuid, p_consequence_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_user UUID := auth.uid();
  v_session public.sessions%ROWTYPE;
  v_project public.projects%ROWTYPE;
  v_def public.saga_definitions%ROWTYPE;
  v_ver public.saga_definition_versions%ROWTYPE;
  v_cons JSONB;
  v_fact_id TEXT;
  v_visibility TEXT;
  v_summary TEXT;
  v_facts JSONB;
  v_exists BOOLEAN;
  v_promo public.session_outcome_promotions%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_project FROM public.projects WHERE id = v_session.project_id;
  IF NOT public.is_project_gm(v_project.id, v_user) THEN
    RAISE EXCEPTION 'Nur Gamemaster darf übernehmen' USING ERRCODE = '42501';
  END IF;

  IF v_project.saga_id IS NULL THEN
    RAISE EXCEPTION 'Keine Saga-Definition an diese Gruppe gebunden' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_def FROM public.saga_definitions WHERE id = v_project.saga_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saga-Definition nicht gefunden' USING ERRCODE = 'P0002';
  END IF;
  IF v_def.origin = 'native' THEN
    RAISE EXCEPTION 'Native Sagas sind unveränderlich — bitte zuerst als Kopie speichern' USING ERRCODE = '42501';
  END IF;
  IF v_def.owner_user_id IS DISTINCT FROM v_user THEN
    RAISE EXCEPTION 'Nur die Autorin/der Autor der Saga darf in die Definition übernehmen' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_promo
  FROM public.session_outcome_promotions
  WHERE project_id = v_project.id
    AND source_kind = 'consequence'
    AND source_id = p_consequence_id
    AND target_kind = 'saga_fact';
  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'targetKind', 'saga_fact',
      'targetRef', v_promo.target_ref
    );
  END IF;

  v_cons := public.sagatree_find_session_consequence(p_session_id, p_consequence_id);
  IF v_cons IS NULL THEN
    RAISE EXCEPTION 'Ereignis nicht gefunden' USING ERRCODE = 'P0002';
  END IF;

  v_summary := NULLIF(BTRIM(COALESCE(v_cons->>'summary', '')), '');
  IF v_summary IS NULL THEN
    RAISE EXCEPTION 'Ereignis ohne Text' USING ERRCODE = '22023';
  END IF;
  v_visibility := COALESCE(NULLIF(BTRIM(v_cons->>'visibility'), ''), 'shared');
  IF v_visibility NOT IN ('public', 'shared', 'gm_only', 'discovered', 'character_specific') THEN
    v_visibility := 'shared';
  END IF;
  v_fact_id := 'promoted:' || left(p_consequence_id, 64);

  v_ver := public.sagatree_ensure_saga_draft(v_def.id);
  v_facts := COALESCE(v_ver.payload->'knowledgeFacts', '[]'::jsonb);

  SELECT EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_facts) AS f
    WHERE f->>'id' = v_fact_id
  ) INTO v_exists;

  IF NOT v_exists THEN
    v_facts := v_facts || jsonb_build_array(
      jsonb_build_object(
        'id', v_fact_id,
        'visibility', v_visibility,
        'summary', left(v_summary, 200)
      )
    );
    UPDATE public.saga_definition_versions
       SET payload = jsonb_set(
         COALESCE(payload, '{}'::jsonb),
         '{knowledgeFacts}',
         v_facts,
         true
       )
     WHERE id = v_ver.id;
    UPDATE public.saga_definitions
       SET draft_revision = draft_revision + 1,
           updated_at = NOW()
     WHERE id = v_def.id;
  END IF;

  INSERT INTO public.session_outcome_promotions (
    project_id, session_id, source_kind, source_id, target_kind, target_ref, created_by
  ) VALUES (
    v_project.id, p_session_id, 'consequence', p_consequence_id, 'saga_fact', v_fact_id, v_user
  );

  PERFORM public.append_session_event(
    p_session_id,
    'adventure',
    v_user,
    jsonb_build_object(
      'op', 'promote_outcome',
      'target', 'saga',
      'consequenceId', p_consequence_id,
      'factId', v_fact_id
    ),
    COALESCE(v_session.runtime_revision, 0),
    'promote-saga:' || p_consequence_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'targetKind', 'saga_fact',
    'targetRef', v_fact_id,
    'messageDe', 'In die Saga-Definition übernommen (Entwurf).'
  );
END;
$$

