CREATE OR REPLACE FUNCTION public.set_saga_binding_reveal(p_project_id uuid, p_binding_id uuid, p_reveal text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_row public.saga_asset_bindings%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF p_reveal NOT IN ('gm_only', 'party', 'unlisted') THEN
    RAISE EXCEPTION 'invalid reveal %', p_reveal;
  END IF;
  IF NOT public.has_saga_permission(p_project_id, 'saga.secrets.reveal')
     AND NOT public.is_project_gm(p_project_id, v_uid) THEN
    RAISE EXCEPTION 'missing saga.secrets.reveal';
  END IF;

  UPDATE public.saga_asset_bindings
  SET reveal = p_reveal, updated_at = NOW()
  WHERE id = p_binding_id AND project_id = p_project_id
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'binding not found';
  END IF;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'assetKind', v_row.asset_kind,
    'assetId', v_row.asset_id,
    'reveal', v_row.reveal,
    'label', v_row.label
  );
END;
$$

CREATE OR REPLACE FUNCTION public.set_saga_member_bundle(p_project_id uuid, p_member_id uuid, p_bundle_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_member RECORD;
  v_governance_left INT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF NOT public.has_saga_permission(p_project_id, 'saga.members.set_bundle')
     AND NOT public.is_project_gm(p_project_id, v_uid) THEN
    RAISE EXCEPTION 'missing saga.members.set_bundle';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.saga_permission_bundles WHERE id = p_bundle_id) THEN
    RAISE EXCEPTION 'unknown bundle %', p_bundle_id;
  END IF;

  SELECT * INTO v_member
  FROM public.project_members
  WHERE id = p_member_id AND project_id = p_project_id AND status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'member not found';
  END IF;

  -- Invariant: cannot demote last holder of set_bundle away from GM bundle.
  IF p_bundle_id <> 'bundle.saga.gm' THEN
    SELECT COUNT(DISTINCT g.user_id) INTO v_governance_left
    FROM public.project_member_saga_grants g
    JOIN public.project_members m ON m.id = g.member_id
    WHERE g.project_id = p_project_id
      AND g.permission_key = 'saga.members.set_bundle'
      AND m.status = 'active'
      AND g.member_id <> p_member_id;
    IF COALESCE(v_governance_left, 0) < 1
       AND EXISTS (
         SELECT 1 FROM public.project_member_saga_grants
         WHERE member_id = p_member_id AND permission_key = 'saga.members.set_bundle'
       ) THEN
      RAISE EXCEPTION 'cannot revoke last saga.members.set_bundle grant';
    END IF;
  END IF;

  DELETE FROM public.project_member_saga_grants WHERE member_id = p_member_id;

  INSERT INTO public.project_member_saga_grants (
    project_id, member_id, user_id, permission_key, source_bundle_id, granted_by
  )
  SELECT
    p_project_id,
    p_member_id,
    v_member.user_id,
    bk.permission_key,
    p_bundle_id,
    v_uid
  FROM public.saga_permission_bundle_keys bk
  WHERE bk.bundle_id = p_bundle_id;

  INSERT INTO public.project_member_saga_bundles (
    member_id, project_id, user_id, bundle_id, assigned_by, updated_at
  ) VALUES (
    p_member_id, p_project_id, v_member.user_id, p_bundle_id, v_uid, NOW()
  )
  ON CONFLICT (member_id) DO UPDATE SET
    bundle_id = EXCLUDED.bundle_id,
    assigned_by = EXCLUDED.assigned_by,
    updated_at = NOW();

  RETURN jsonb_build_object(
    'memberId', p_member_id,
    'bundleId', p_bundle_id,
    'grantCount', (
      SELECT COUNT(*)::INT FROM public.project_member_saga_grants WHERE member_id = p_member_id
    )
  );
END;
$$

CREATE OR REPLACE FUNCTION public.set_session_player_presence(p_session_id uuid, p_is_online boolean, p_expected_revision bigint = NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_revision BIGINT;
BEGIN
  IF actor IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_session_participant(p_session_id, actor) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_expected_revision IS NOT NULL
     AND v_session.runtime_revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'stale revision: expected %, actual %',
      p_expected_revision, v_session.runtime_revision
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.session_players
     SET is_online = COALESCE(p_is_online, false)
   WHERE session_id = p_session_id AND user_id = actor;

  v_revision := v_session.runtime_revision + 1;
  UPDATE public.sessions
     SET runtime_revision = v_revision, updated_at = NOW()
   WHERE id = p_session_id;

  PERFORM public.append_session_event(
    p_session_id,
    'presence',
    actor,
    jsonb_build_object('isOnline', COALESCE(p_is_online, false)),
    v_revision,
    NULL
  );

  RETURN public.get_session_runtime_snapshot(p_session_id);
END;
$$

CREATE OR REPLACE FUNCTION public.set_session_status(p_session_id uuid, p_status text) RETURNS public.sessions LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  actor UUID := auth.uid();
  v_session public.sessions;
  v_from TEXT;
  v_revision BIGINT;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  IF p_status NOT IN ('waiting', 'active', 'paused', 'completed') THEN
    RAISE EXCEPTION 'Invalid session status' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_session FROM public.sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Session not found' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.is_project_gm(v_session.project_id, actor) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  v_from := v_session.status;
  IF v_from = 'scheduled' THEN v_from := 'waiting'; END IF;
  IF v_from = 'completed' THEN RAISE EXCEPTION 'Completed sessions cannot change status' USING ERRCODE = '22023'; END IF;
  IF NOT (
    (v_from = 'waiting' AND p_status IN ('active', 'completed'))
    OR (v_from = 'active' AND p_status IN ('paused', 'completed'))
    OR (v_from = 'paused' AND p_status IN ('active', 'completed'))
  ) THEN
    RAISE EXCEPTION 'Illegal status transition from % to %', v_from, p_status USING ERRCODE = '22023';
  END IF;

  v_revision := COALESCE(v_session.runtime_revision, 0) + 1;

  UPDATE public.sessions SET
    status = p_status,
    runtime_revision = v_revision,
    updated_at = NOW(),
    started_at = CASE WHEN p_status = 'active' AND started_at IS NULL THEN NOW() ELSE started_at END,
    ended_at = CASE WHEN p_status = 'completed' THEN NOW() ELSE ended_at END
  WHERE id = p_session_id
  RETURNING * INTO v_session;

  PERFORM public.append_session_event(
    p_session_id,
    'status',
    actor,
    jsonb_build_object('from', v_from, 'to', p_status),
    v_revision,
    NULL
  );

  IF p_status = 'completed' THEN
    PERFORM public.sagatree_upsert_session_recap(p_session_id);
  END IF;

  RETURN v_session;
END;
$$

CREATE OR REPLACE FUNCTION public.spawn_npc_creature_instance(p_project_id uuid, p_definition_id text, p_instance_kind text, p_snapshot jsonb, p_runtime jsonb, p_display_name text, p_sequence_number integer, p_session_id uuid = NULL) RETURNS public.npc_creature_instances LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_actor UUID;
  v_definition_id TEXT := btrim(COALESCE(p_definition_id, ''));
  v_display_name TEXT := btrim(COALESCE(p_display_name, ''));
  v_kind TEXT := btrim(COALESCE(p_instance_kind, ''));
  v_row public.npc_creature_instances;
  v_session_project UUID;
BEGIN
  v_actor := public.assert_npc_creature_instance_gm(p_project_id);

  IF char_length(v_definition_id) < 10 OR char_length(v_definition_id) > 160 THEN
    RAISE EXCEPTION 'invalid definition id';
  END IF;

  IF v_kind NOT IN ('generic', 'persistent') THEN
    RAISE EXCEPTION 'invalid instance kind';
  END IF;

  IF char_length(v_display_name) < 1 OR char_length(v_display_name) > 120 THEN
    RAISE EXCEPTION 'invalid display name';
  END IF;

  IF p_sequence_number IS NULL OR p_sequence_number < 1 THEN
    RAISE EXCEPTION 'invalid sequence number';
  END IF;

  IF jsonb_typeof(p_snapshot) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid snapshot';
  END IF;

  IF jsonb_typeof(p_runtime) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid runtime';
  END IF;

  -- Persistent uniques are campaign-scoped (no session).
  IF v_kind = 'persistent' AND p_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'persistent instances must not bind a session';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT s.project_id INTO v_session_project
    FROM public.sessions s
    WHERE s.id = p_session_id;
    IF v_session_project IS NULL OR v_session_project IS DISTINCT FROM p_project_id THEN
      RAISE EXCEPTION 'session does not belong to project';
    END IF;
  END IF;

  -- Definition reference validation:
  -- - core:/builtin: ids are snapshot-only (no DB row required)
  -- - personal:/world: must exist and be readable by actor (or archived but still present)
  IF v_definition_id LIKE 'personal:%' OR v_definition_id LIKE 'world:%' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.npc_creature_definitions d
      WHERE d.id = v_definition_id
        AND (
          (d.scope = 'personal' AND d.owner_user_id = v_actor)
          OR (d.scope = 'world' AND public.current_user_can_read_world_profile(d.world_profile_id))
        )
    ) THEN
      RAISE EXCEPTION 'definition not readable';
    END IF;
  END IF;

  -- Temp controller inside runtime must be null or active member.
  IF p_runtime ? 'temporaryControllerUserId'
     AND jsonb_typeof(p_runtime->'temporaryControllerUserId') = 'string'
     AND btrim(p_runtime->>'temporaryControllerUserId') <> '' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.project_members pm
      WHERE pm.project_id = p_project_id
        AND pm.user_id = (p_runtime->>'temporaryControllerUserId')::uuid
        AND pm.status = 'active'
    ) THEN
      RAISE EXCEPTION 'temporary controller is not an active project member';
    END IF;
  END IF;

  INSERT INTO public.npc_creature_instances (
    project_id,
    session_id,
    definition_id,
    display_name,
    instance_kind,
    sequence_number,
    snapshot,
    runtime,
    created_by,
    created_at,
    updated_at
  )
  VALUES (
    p_project_id,
    CASE WHEN v_kind = 'persistent' THEN NULL ELSE p_session_id END,
    v_definition_id,
    v_display_name,
    v_kind,
    p_sequence_number,
    p_snapshot,
    p_runtime,
    v_actor,
    NOW(),
    NOW()
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$

CREATE OR REPLACE FUNCTION public.update_npc_creature_instance_runtime(p_instance_id uuid, p_runtime jsonb) RETURNS public.npc_creature_instances LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  v_row public.npc_creature_instances;
  v_actor UUID;
BEGIN
  IF p_instance_id IS NULL THEN
    RAISE EXCEPTION 'missing instance';
  END IF;

  IF jsonb_typeof(p_runtime) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid runtime';
  END IF;

  SELECT * INTO v_row
  FROM public.npc_creature_instances
  WHERE id = p_instance_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'instance not found';
  END IF;

  v_actor := public.assert_npc_creature_instance_gm(v_row.project_id);

  IF p_runtime ? 'temporaryControllerUserId'
     AND jsonb_typeof(p_runtime->'temporaryControllerUserId') = 'string'
     AND btrim(p_runtime->>'temporaryControllerUserId') <> '' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.project_members pm
      WHERE pm.project_id = v_row.project_id
        AND pm.user_id = (p_runtime->>'temporaryControllerUserId')::uuid
        AND pm.status = 'active'
    ) THEN
      RAISE EXCEPTION 'temporary controller is not an active project member';
    END IF;
  END IF;

  -- Snapshot column intentionally untouched.
  UPDATE public.npc_creature_instances
  SET runtime = p_runtime,
      updated_at = NOW()
  WHERE id = p_instance_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$

CREATE OR REPLACE FUNCTION update_updated_at_column() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION public.upsert_world_atlas_map(p_world_profile_id uuid, p_map_id uuid, p_parent_map_id uuid, p_kind text, p_title text, p_sort_order integer, p_bounds jsonb, p_layers jsonb, p_basemap_storage_path text, p_azgaar_map_storage_path text, p_generator_meta jsonb, p_expected_revision bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_user UUID := auth.uid();
  v_id UUID;
  v_rev BIGINT;
  v_kind TEXT := COALESCE(NULLIF(trim(p_kind), ''), 'world');
  v_title TEXT := COALESCE(NULLIF(trim(p_title), ''), 'Weltkarte');
  v_layers JSONB := COALESCE(p_layers, '{"type":"FeatureCollection","features":[]}'::jsonb);
  v_bounds JSONB := COALESCE(p_bounds, '{"minX":0,"minY":0,"maxX":1000,"maxY":1000}'::jsonb);
  v_meta JSONB := COALESCE(p_generator_meta, '{}'::jsonb);
  v_layer_bytes INT;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_world_profile_id IS NULL THEN
    RAISE EXCEPTION 'world_profile_id required' USING ERRCODE = '22023';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_kind NOT IN ('world', 'region', 'settlement', 'scene', 'legacy_tiles') THEN
    RAISE EXCEPTION 'invalid kind' USING ERRCODE = '22023';
  END IF;

  v_layer_bytes := octet_length(v_layers::text);
  IF v_layer_bytes > 1500000 THEN
    RAISE EXCEPTION 'layers too large' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(jsonb_typeof(v_layers), '') <> 'object'
     OR COALESCE(v_layers->>'type', '') <> 'FeatureCollection' THEN
    RAISE EXCEPTION 'layers must be a GeoJSON FeatureCollection' USING ERRCODE = '22023';
  END IF;

  IF p_parent_map_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.world_atlas_maps p
      WHERE p.id = p_parent_map_id AND p.world_profile_id = p_world_profile_id
    ) THEN
      RAISE EXCEPTION 'parent map not in world' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_map_id IS NULL THEN
    INSERT INTO public.world_atlas_maps (
      world_profile_id, parent_map_id, kind, title, sort_order,
      bounds, layers, basemap_storage_path, azgaar_map_storage_path, generator_meta, revision
    ) VALUES (
      p_world_profile_id, p_parent_map_id, v_kind, v_title, COALESCE(p_sort_order, 0),
      v_bounds, v_layers, p_basemap_storage_path, p_azgaar_map_storage_path, v_meta, 1
    )
    RETURNING id, revision INTO v_id, v_rev;
  ELSE
    UPDATE public.world_atlas_maps m
    SET
      parent_map_id = p_parent_map_id,
      kind = v_kind,
      title = v_title,
      sort_order = COALESCE(p_sort_order, m.sort_order),
      bounds = v_bounds,
      layers = v_layers,
      basemap_storage_path = COALESCE(p_basemap_storage_path, m.basemap_storage_path),
      azgaar_map_storage_path = COALESCE(p_azgaar_map_storage_path, m.azgaar_map_storage_path),
      generator_meta = v_meta,
      revision = m.revision + 1,
      updated_at = now()
    WHERE m.id = p_map_id
      AND m.world_profile_id = p_world_profile_id
      AND m.revision = COALESCE(p_expected_revision, m.revision)
    RETURNING id, revision INTO v_id, v_rev;

    IF v_id IS NULL THEN
      RAISE EXCEPTION 'revision conflict or map not found' USING ERRCODE = '40001';
    END IF;
  END IF;

  RETURN public.get_world_atlas_map(v_id, false);
END;
$$

CREATE OR REPLACE FUNCTION public.upsert_world_place(p_world_profile_id uuid, p_place_id uuid, p_parent_place_id uuid, p_kind text, p_name text, p_description text, p_status text, p_seed_key text, p_sort_order integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_user UUID := auth.uid();
  v_row public.world_places%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_kind IS NULL OR p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'kind and name required' USING ERRCODE = '22023';
  END IF;

  IF p_place_id IS NULL THEN
    INSERT INTO public.world_places (
      world_profile_id, parent_place_id, kind, name, description, status, seed_key, sort_order
    ) VALUES (
      p_world_profile_id,
      p_parent_place_id,
      p_kind,
      btrim(p_name),
      NULLIF(btrim(COALESCE(p_description, '')), ''),
      COALESCE(NULLIF(p_status, ''), 'draft'),
      NULLIF(btrim(COALESCE(p_seed_key, '')), ''),
      COALESCE(p_sort_order, 0)
    )
    RETURNING * INTO v_row;
  ELSE
    UPDATE public.world_places
    SET
      parent_place_id = p_parent_place_id,
      kind = p_kind,
      name = btrim(p_name),
      description = NULLIF(btrim(COALESCE(p_description, '')), ''),
      status = COALESCE(NULLIF(p_status, ''), status),
      seed_key = COALESCE(NULLIF(btrim(COALESCE(p_seed_key, '')), ''), seed_key),
      sort_order = COALESCE(p_sort_order, sort_order),
      revision = revision + 1,
      updated_at = NOW()
    WHERE id = p_place_id AND world_profile_id = p_world_profile_id
    RETURNING * INTO v_row;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'not found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'worldProfileId', v_row.world_profile_id,
    'parentPlaceId', v_row.parent_place_id,
    'kind', v_row.kind,
    'name', v_row.name,
    'description', v_row.description,
    'status', v_row.status,
    'seedKey', v_row.seed_key,
    'sortOrder', v_row.sort_order,
    'revision', v_row.revision
  );
END;
$$

CREATE OR REPLACE FUNCTION public.upsert_world_place_map_link(p_world_profile_id uuid, p_place_id uuid, p_map_id uuid, p_usage text, p_feature_id text = NULL, p_anchor jsonb = CAST('{}' AS jsonb)) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_user UUID := auth.uid();
  v_row public.world_place_map_links%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT public.current_user_can_edit_world_profile(p_world_profile_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_place_id IS NULL OR p_map_id IS NULL OR p_usage IS NULL OR btrim(p_usage) = '' THEN
    RAISE EXCEPTION 'place, map and usage required' USING ERRCODE = '22023';
  END IF;

  -- Same-world: place and map must belong to the world profile.
  IF NOT EXISTS (
    SELECT 1 FROM public.world_places p
    WHERE p.id = p_place_id AND p.world_profile_id = p_world_profile_id
  ) THEN
    RAISE EXCEPTION 'place not in world' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.world_atlas_maps m
    WHERE m.id = p_map_id AND m.world_profile_id = p_world_profile_id
  ) THEN
    RAISE EXCEPTION 'map not in world' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.world_place_map_links (
    world_profile_id, place_id, map_id, usage, feature_id, anchor
  ) VALUES (
    p_world_profile_id,
    p_place_id,
    p_map_id,
    btrim(p_usage),
    NULLIF(btrim(COALESCE(p_feature_id, '')), ''),
    COALESCE(p_anchor, '{}'::jsonb)
  )
  ON CONFLICT (place_id, map_id, usage) DO UPDATE
    SET feature_id = EXCLUDED.feature_id,
        anchor = EXCLUDED.anchor
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'worldProfileId', v_row.world_profile_id,
    'placeId', v_row.place_id,
    'mapId', v_row.map_id,
    'usage', v_row.usage,
    'featureId', v_row.feature_id,
    'anchor', v_row.anchor
  );
END;
$$

CREATE OR REPLACE FUNCTION public.world_place_map_links_enforce_same_world() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.world_places p
    WHERE p.id = NEW.place_id AND p.world_profile_id = NEW.world_profile_id
  ) THEN
    RAISE EXCEPTION 'place/map link world mismatch (place)' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.world_atlas_maps m
    WHERE m.id = NEW.map_id AND m.world_profile_id = NEW.world_profile_id
  ) THEN
    RAISE EXCEPTION 'place/map link world mismatch (map)' USING ERRCODE = '23514';
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.world_places_enforce_same_world() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $$
BEGIN
  IF NEW.parent_place_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.world_places p
      WHERE p.id = NEW.parent_place_id
        AND p.world_profile_id = NEW.world_profile_id
    ) THEN
      RAISE EXCEPTION 'parent_place must be in same world' USING ERRCODE = '23514';
    END IF;
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$
